INSERT INTO `Package` (`slug`, `name`, `category`, `country`, `region`, `city`, `tagline`, `nights`, `days`, `occupancy`, `price`, `currency`, `hotelStars`, `rating`, `featured`, `published`, `order`, `image`, `gallery`, `tags`, `includes`, `highlights`, `itinerary`, `createdAt`, `updatedAt`) VALUES
  ('escape-to-armenia', 'Armenia Tour', 'tour', 'Armenia', 'Caucasus', 'Yerevan', 'Experience Armenia''s winter charm. Escape to the breathtaking landscapes of Armenia this winter with our 3 Nights / 4 Days tour package. From snow-covered mountains and cozy villages to vibrant city life in Yerevan, this journey offers the perfect mix of adventure, culture and relaxation.', 3, 4, 'Quad sharing', 1999, 'AED', 4, 4.9, 1, 1, 0, 'https://images.unsplash.com/photo-1585687501004-615dfdfb6f37?auto=format&fit=crop&w=1200&q=80', '["https://images.unsplash.com/photo-1585687501004-615dfdfb6f37?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1600241318523-1a2a56b8a41f?auto=format&fit=crop&w=1200&q=80"]', '["Culture","Nature","Winter","Best Seller"]', '["Return flights from UAE","4★ hotel stay","Daily breakfast","Airport transfers","Yerevan city tour"]', '["Explore Yerevan","Lake Sevan — the Pearl of Armenia","Garni Temple & Geghard","Cascade Complex"]', '[{"day":1,"title":"Arrival in Yerevan","detail":"Warm welcome at Zvartnots Airport, private transfer to your 4★ hotel and an evening stroll along Republic Square."},{"day":2,"title":"Yerevan City & Cascade","detail":"Discover the pink-stone capital — the Cascade Complex, Opera House, museums and vibrant cafés."},{"day":3,"title":"Lake Sevan & Highlands","detail":"Day trip to the sparkling Lake Sevan, Sevanavank monastery and the alpine countryside."},{"day":4,"title":"Departure","detail":"Leisurely breakfast, last-minute souvenir shopping and transfer back to the airport."}]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('georgia-highlights', 'Georgia Tour', 'tour', 'Georgia', 'Caucasus', 'Tbilisi', 'Discover the beauty of Georgia with this 2-night, 3-day tour. Includes a 4★ hotel stay, transfers, daily breakfast, and day trips to Tbilisi, Narikala Fortress and the Bridge of Peace.', 2, 3, 'Triple sharing', 1499, 'AED', 4, 4.8, 0, 1, 1, 'https://images.unsplash.com/photo-1565008576549-57569a49371d?auto=format&fit=crop&w=1200&q=80', '["https://images.unsplash.com/photo-1565008576549-57569a49371d?auto=format&fit=crop&w=1200&q=80"]', '["Culture","Nature","City Break"]', '["4★ hotel stay","Airport transfers","Daily breakfast","Day trips & sightseeing"]', '["Tbilisi city tour","Narikala Fortress","Bridge of Peace"]', '[{"day":1,"title":"Arrival in Tbilisi","detail":"Transfer to hotel and an evening walk through the atmospheric old town."},{"day":2,"title":"Tbilisi City Tour","detail":"Narikala Fortress, the Bridge of Peace, sulphur baths and the charming backstreets."},{"day":3,"title":"Departure","detail":"Breakfast and airport transfer."}]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('baku-azerbaijan', 'Azerbaijan, Baku Tour', 'tour', 'Azerbaijan', 'Caucasus', 'Baku', 'Enjoy a 3-night, 4-day Baku tour featuring a 4★ hotel stay, included transfers, daily breakfast, and day trips to Nizami Street and the Flame Towers.', 3, 4, 'Twin sharing', 1999, 'AED', 4, 4.7, 0, 1, 2, 'https://images.unsplash.com/photo-1601921004897-c1e6d1f9a4d4?auto=format&fit=crop&w=1200&q=80', '["https://images.unsplash.com/photo-1601921004897-c1e6d1f9a4d4?auto=format&fit=crop&w=1200&q=80"]', '["City Break","Culture"]', '["4★ hotel stay","Airport transfers","Daily breakfast","Day trips & sightseeing"]', '["Nizami Street","Flame Towers","Icherisheher Old City","Caspian promenade"]', '[{"day":1,"title":"Arrival in Baku","detail":"Transfer to hotel and a stroll along the Caspian boulevard."},{"day":2,"title":"Old & New Baku","detail":"Icherisheher old city, Maiden Tower and the futuristic Flame Towers."},{"day":3,"title":"Nizami Street & Beyond","detail":"Day trip along Nizami Street, Fountain Square and Highland Park views."},{"day":4,"title":"Departure","detail":"Breakfast and airport transfer."}]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('discover-istanbul', 'Turkey, Istanbul Tour', 'tour', 'Türkiye', 'Europe & Asia', 'Istanbul', 'Embark on a journey to Turkey, a land where history, culture and natural beauty come together in perfect harmony.', 3, 4, 'Twin sharing', 2199, 'AED', 4, 4.8, 1, 1, 3, 'https://images.unsplash.com/photo-1524231757912-21f4fe3a7200?auto=format&fit=crop&w=1200&q=80', '["https://images.unsplash.com/photo-1524231757912-21f4fe3a7200?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1541432901042-2d8bd64b4a9b?auto=format&fit=crop&w=1200&q=80"]', '["Culture","City Break","Popular"]', '["Return flights from UAE","4★ hotel stay","Daily breakfast","Airport transfers","Bosphorus cruise"]', '["Blue Mosque & Hagia Sophia","Grand Bazaar","Bosphorus dinner cruise","Topkapi Palace"]', '[{"day":1,"title":"Arrival in Istanbul","detail":"Private transfer to your hotel in the heart of the old city, evening at leisure."},{"day":2,"title":"Old City Wonders","detail":"Hagia Sophia, the Blue Mosque, Topkapi Palace and the Hippodrome."},{"day":3,"title":"Bazaars & Bosphorus","detail":"The Grand Bazaar, Spice Market and an unforgettable Bosphorus dinner cruise."},{"day":4,"title":"Departure","detail":"Breakfast and airport transfer with memories to last a lifetime."}]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('russian-adventure', 'Russia, Moscow Tour', 'tour', 'Russia', 'Europe', 'Moscow', 'Explore the iconic landmarks of Moscow, from the Kremlin and Red Square to the colourful domes of St Basil''s Cathedral. Discover the elegance of St Petersburg, with its royal palaces, canals and world-class museums like the Hermitage. Whether it''s walking through centuries of history, enjoying the vibrant cultural scene or admiring breathtaking architecture, Russia offers a journey unlike any other.', 3, 4, 'Twin sharing', 3555, 'AED', 4, 4.9, 1, 1, 4, 'https://images.unsplash.com/photo-1513326738677-b964603b136d?auto=format&fit=crop&w=1200&q=80', '["https://images.unsplash.com/photo-1513326738677-b964603b136d?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1547448415-e9f5b28e570d?auto=format&fit=crop&w=1200&q=80"]', '["Culture","City Break"]', '["Return flights from UAE","4★ hotel stay","Daily breakfast","Airport transfers","Kremlin & Red Square tour"]', '["Red Square & St Basil’s","The Kremlin","Moscow Metro tour","St Petersburg & the Hermitage"]', '[{"day":1,"title":"Arrival in Moscow","detail":"Meet & greet, transfer to your central hotel, evening walk to illuminated Red Square."},{"day":2,"title":"Kremlin & Red Square","detail":"Guided tour of the Kremlin, Cathedral Square and iconic St Basil’s Cathedral."},{"day":3,"title":"Metro & Museums","detail":"The palatial Moscow Metro, Tretyakov Gallery and Arbat Street."},{"day":4,"title":"Departure","detail":"Breakfast and transfer to the airport."}]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('maldives-getaway', 'Maldives Tour', 'tour', 'Maldives', 'Indian Ocean', 'Malé', 'Relax in paradise with a 4★ hotel stay, transfers, breakfast, and day trips to Vaadhoo Island, Alimatha Island, Addu Atoll, Banana Reef and Mirihi Island.', 4, 5, 'Twin sharing', 1550, 'AED', 4, 5, 1, 1, 5, 'https://images.unsplash.com/photo-1514282401047-d79a71a590e8?auto=format&fit=crop&w=1200&q=80', '["https://images.unsplash.com/photo-1514282401047-d79a71a590e8?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1573843981267-be1999ff37cd?auto=format&fit=crop&w=1200&q=80"]', '["Beach","Honeymoon","Islands"]', '["4★ hotel stay","Airport transfers","Daily breakfast","Island day trips"]', '["Vaadhoo Island","Alimatha Island","Addu Atoll","Banana Reef","Mirihi Island"]', '[{"day":1,"title":"Arrival in Malé","detail":"Transfer to your hotel, welcome drinks and check-in."},{"day":2,"title":"Reef & Lagoon","detail":"Snorkelling over Banana Reef and a lazy afternoon by the lagoon."},{"day":3,"title":"Island Hopping","detail":"Day trips to Vaadhoo and Alimatha islands."},{"day":4,"title":"Atolls & Relaxation","detail":"Addu Atoll and Mirihi Island, then beachfront dining."},{"day":5,"title":"Departure","detail":"Final breakfast and transfer back to Malé."}]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('dubai-city-experience', 'Dubai City Experience', 'tour', 'United Arab Emirates', 'Middle East', 'Dubai', 'Sky-high glamour, golden dunes and modern marvels', 3, 4, 'Twin sharing', 1890, 'AED', 5, 4.9, 0, 1, 6, 'https://images.unsplash.com/photo-1512453979798-5ea266f8880c?auto=format&fit=crop&w=1200&q=80', '["https://images.unsplash.com/photo-1512453979798-5ea266f8880c?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1518684079-3c830dcef090?auto=format&fit=crop&w=1200&q=80"]', '["City Break","Family","Luxury"]', '["5★ hotel stay","Daily breakfast","Desert safari","Burj Khalifa tickets"]', '["Burj Khalifa At The Top","Desert safari & BBQ","Dhow dinner cruise","Dubai Mall & Fountain"]', '[{"day":1,"title":"Arrival in Dubai","detail":"Transfer to your 5★ hotel and evening at the Dubai Fountain."},{"day":2,"title":"Modern Dubai","detail":"Burj Khalifa At The Top, Dubai Mall and the Marina."},{"day":3,"title":"Desert Safari","detail":"Dune bashing, camel rides and a starlit BBQ dinner with live shows."},{"day":4,"title":"Departure","detail":"Breakfast and airport transfer."}]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('egypt-cairo-tour', 'Egypt, Cairo Tour', 'tour', 'Egypt', 'Africa', 'Cairo', 'Uncover the wonders of Egypt with our exclusive tour package, where every moment takes you closer to the cradle of civilisation. Marvel at the majestic Pyramids of Giza and the Great Sphinx, cruise along the legendary Nile River, and explore ancient temples that whisper stories of powerful pharaohs.', 3, 4, '', 2050, 'AED', 4, 5, 0, 1, 7, '', '[]', '["Culture","History"]', '[]', '["Pyramids of Giza","The Great Sphinx","Nile River cruise","Ancient temples"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('singapore-tour', 'Singapore Tour', 'tour', 'Singapore', 'Southeast Asia', 'Singapore', 'Discover the perfect blend of modern marvels and natural beauty with our Singapore tour package. From the dazzling Marina Bay Sands and Gardens by the Bay to the thrilling Sentosa Island and vibrant cultural streets, Singapore is a destination that has it all.', 2, 3, '', 2550, 'AED', 4, 5, 0, 1, 8, '', '[]', '["City Break","Family"]', '[]', '["Marina Bay Sands","Gardens by the Bay","Sentosa Island","Cultural streets"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('nairobi-kenya-tour', 'Nairobi, Kenya Tour', 'tour', 'Kenya', 'Africa', 'Nairobi', 'Embark on an unforgettable journey to Nairobi, Kenya, the vibrant capital that blends urban charm with thrilling wildlife adventures. Known as the “Safari Capital of the World”, Nairobi offers a rare experience where modern city life meets breathtaking nature. Visit the famous Nairobi National Park, where lions, giraffes and rhinos roam against a backdrop of the city skyline, and explore attractions like the Giraffe Centre and the David Sheldrick Elephant Orphanage.', 4, 5, '', 5500, 'AED', 4, 5, 0, 1, 9, '', '[]', '["Safari","Wildlife","Adventure"]', '[]', '["Nairobi National Park","Giraffe Centre","David Sheldrick Elephant Orphanage","Local markets & cuisine"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('sri-lanka-tour', 'Sri Lanka Tour', 'tour', 'Sri Lanka', 'South Asia', 'Colombo', 'Discover the tropical paradise of Sri Lanka, an island that offers a perfect blend of golden beaches, lush green landscapes and rich cultural heritage. From the ancient cities of Sigiriya and Kandy to the scenic tea plantations of Nuwara Eliya and the wildlife safaris in Yala National Park, every corner of Sri Lanka tells a unique story.', 3, 4, '', 2155, 'AED', 4, 5, 0, 1, 10, '', '[]', '["Beach","Culture","Nature"]', '[]', '["Sigiriya","Kandy","Nuwara Eliya tea plantations","Yala National Park safari"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('northern-lights-russia-tour', 'Northern Lights Russia Tour', 'tour', 'Russia', 'Europe', 'Murmansk', 'Witness the magic of the Northern Lights in Russia with our unforgettable tour package designed for adventure and wonder. Journey to the breathtaking Kola Peninsula and beyond, where the Arctic skies light up in a dazzling dance of colours. Along the way, explore charming snow-covered landscapes, experience authentic Russian winter traditions, and enjoy activities like husky sledding and reindeer rides.', 4, 5, '', 7999, 'AED', 4, 5, 0, 1, 11, '', '[]', '["Winter","Adventure","Aurora"]', '[]', '["Kola Peninsula aurora viewing","Husky sledding","Reindeer rides","Russian winter traditions"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('athens-greece-tour', 'Athens, Greece Tour', 'tour', 'Greece', 'Europe', 'Athens', 'Discover the timeless beauty of Greece, a destination where history, culture and natural wonders come together. Walk through the ancient ruins of Athens, stand in awe at the Acropolis, and dive into the mythology that shaped Western civilisation. Then unwind on the stunning islands of Santorini, Mykonos or Crete, where whitewashed houses, turquoise waters and breathtaking sunsets await.', 3, 4, '', 3999, 'AED', 4, 5, 0, 1, 12, '', '[]', '["Culture","History","Beach"]', '[]', '["The Acropolis","Ancient Athens ruins","Santorini, Mykonos & Crete","Mediterranean cuisine"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('bali-indonesia-tour', 'Bali, Indonesia Tour', 'tour', 'Indonesia', 'Southeast Asia', 'Bali', 'Escape to the tropical paradise of Bali, Indonesia, where serene beaches, lush rice terraces and vibrant culture create the ultimate holiday experience. Explore the island''s spiritual side with visits to ancient temples like Tanah Lot and Uluwatu, or indulge in adventure with surfing, snorkelling and hiking up Mount Batur for a breathtaking sunrise view.', 4, 5, '', 4455, 'AED', 4, 5, 1, 1, 13, '', '[]', '["Beach","Culture","Honeymoon"]', '[]', '["Tanah Lot & Uluwatu temples","Mount Batur sunrise hike","Lush rice terraces","Surfing & snorkelling"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('phuket-thailand-tour', 'Phuket, Thailand Tour', 'tour', 'Thailand', 'Southeast Asia', 'Phuket', 'Discover the tropical charm of Phuket, Thailand, a world-famous destination known for its stunning beaches, vibrant nightlife and cultural treasures. Relax on golden shores like Patong, Kata and Karon, or take a boat trip to the breathtaking Phi Phi Islands and Phang Nga Bay. Explore the rich culture of Old Phuket Town, visit sacred temples, and enjoy authentic Thai cuisine.', 2, 3, '', 3440, 'AED', 4, 5, 1, 1, 14, '', '[]', '["Beach","Islands","Nightlife"]', '[]', '["Patong, Kata & Karon beaches","Phi Phi Islands","Phang Nga Bay","Old Phuket Town"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('madrid-spain-tour', 'Madrid, Spain Tour', 'tour', 'Spain', 'Europe', 'Madrid', 'Uncover the vibrant spirit of Madrid, Spain, a city that perfectly combines history, culture and modern charm. Stroll through grand boulevards and elegant plazas like Puerta del Sol and Plaza Mayor, explore world-class museums such as the Prado and Reina Sofía, and marvel at the royal beauty of the Palacio Real. Savour authentic Spanish flavours with tapas and paella, and experience the passion of flamenco.', 6, 7, '', 6999, 'AED', 4, 5, 0, 1, 15, '', '[]', '["Culture","City Break","Europe"]', '[]', '["Puerta del Sol & Plaza Mayor","Prado & Reina Sofía museums","Palacio Real","Tapas & flamenco"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('milan-italy-tour', 'Milan, Italy Tour', 'tour', 'Italy', 'Europe', 'Milan', 'Experience the elegance of Milan, Italy, a city where fashion, art and history come together in perfect harmony. Explore iconic landmarks like the magnificent Milan Cathedral (Duomo), the historic Galleria Vittorio Emanuele II, and Leonardo da Vinci''s masterpiece, The Last Supper. Stroll through stylish streets lined with world-renowned boutiques, savour authentic Italian cuisine, and enjoy the city''s vibrant nightlife.', 4, 5, '', 5999, 'AED', 4, 5, 0, 1, 16, '', '[]', '["Culture","City Break","Europe"]', '[]', '["Milan Cathedral (Duomo)","Galleria Vittorio Emanuele II","The Last Supper","Fashion district"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('venice-italy-tour', 'Venice, Italy Tour', 'tour', 'Italy', 'Europe', 'Venice', 'Step into the enchanting world of Venice, Italy, a city unlike any other, built on shimmering canals and rich with history and romance. Glide through the waterways on a gondola ride, admire the grandeur of St Mark''s Basilica and the Doge''s Palace, and wander the charming narrow streets that open up to hidden squares and lively piazzas. Explore the colourful islands of Murano and Burano, famous for glassmaking and lace.', 5, 6, '', 6499, 'AED', 4, 5, 0, 1, 17, '', '[]', '["Culture","Honeymoon","Europe"]', '[]', '["Gondola ride on the canals","St Mark’s Basilica","Doge’s Palace","Murano & Burano islands"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('peru-ancient-city-of-incas-tour', 'Peru — The Ancient City of Incas Tour', 'tour', 'Peru', 'South America', 'Cusco', 'Discover the wonders of Peru, the Ancient City of the Incas, where breathtaking landscapes meet one of the world''s greatest civilisations. Journey to the iconic Machu Picchu, a UNESCO World Heritage Site and one of the New Seven Wonders of the World, perched high in the Andes. Explore the Sacred Valley, Cusco''s cobblestone streets, and vibrant local markets filled with rich traditions and colourful crafts.', 6, 7, '', 9999, 'AED', 4, 5, 0, 1, 18, '', '[]', '["Adventure","History","Nature"]', '[]', '["Machu Picchu","The Sacred Valley","Cusco’s cobblestone streets","Lake Titicaca"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('jerusalem-jordan-tour', 'Jerusalem, Jordan Tour', 'tour', 'Jordan', 'Middle East', 'Jerusalem & Petra', 'Explore the spiritual heart of the Middle East with our Jerusalem and Jordan tour package, where history, faith and culture come alive. In Jerusalem, walk through the Old City''s ancient streets and visit sacred sites like the Western Wall, the Church of the Holy Sepulchre and the Dome of the Rock. Continue into Jordan, home to the world-famous city of Petra, along with the mesmerising desert landscapes of Wadi Rum and the healing waters of the Dead Sea.', 4, 5, '', 5999, 'AED', 4, 5, 0, 1, 19, '', '[]', '["Spiritual","Culture","History"]', '[]', '["The Old City & Western Wall","Church of the Holy Sepulchre","Dome of the Rock","Petra & Wadi Rum","The Dead Sea"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('kathmandu-nepal-tour', 'Kathmandu, Nepal Tour', 'tour', 'Nepal', 'South Asia', 'Kathmandu', 'Discover the mystical charm of Kathmandu, Nepal, a city where ancient traditions and vibrant culture meet against the backdrop of the majestic Himalayas. Wander through bustling streets filled with colourful markets, explore UNESCO World Heritage Sites like Swayambhunath (Monkey Temple), Pashupatinath Temple and Durbar Square, and admire centuries-old architecture and spiritual artistry.', 4, 5, '', 1999, 'AED', 4, 5, 0, 1, 20, '', '[]', '["Culture","Spiritual","Nature"]', '[]', '["Swayambhunath (Monkey Temple)","Pashupatinath Temple","Durbar Square","Gateway to the Himalayas"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('seychelles-tour', 'Seychelles Tour', 'tour', 'Seychelles', 'Indian Ocean', 'Victoria', 'Escape to the tropical paradise of Seychelles, a dream destination of pristine white-sand beaches, crystal-clear waters and lush green landscapes. This island haven offers the perfect blend of relaxation and adventure, from snorkelling and diving among vibrant coral reefs to hiking through exotic nature reserves. Explore the charm of Mahé, Praslin and La Digue islands, and indulge in fresh seafood and Creole flavours by the ocean.', 2, 3, '', 4445, 'AED', 4, 5, 0, 1, 21, '', '[]', '["Beach","Islands","Luxury"]', '[]', '["Mahé, Praslin & La Digue","Snorkelling & diving","Exotic nature reserves","Creole seafood"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('dominica-tour', 'Dominica, North America Tour', 'tour', 'Dominica', 'Caribbean', 'Roseau', 'Discover the untouched beauty of Dominica, known as the “Nature Island of the Caribbean”, where lush rainforests, volcanic peaks and pristine waterfalls create a paradise for adventure seekers and nature lovers. Hike through Morne Trois Pitons National Park, a UNESCO World Heritage Site, soak in natural hot springs, and marvel at the famous Boiling Lake. Explore hidden beaches and vibrant coral reefs perfect for diving and snorkelling.', 5, 6, '', 9999, 'AED', 4, 5, 0, 1, 22, '', '[]', '["Nature","Adventure","Beach"]', '[]', '["Morne Trois Pitons National Park","The Boiling Lake","Natural hot springs","Coral reef diving"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('winter-holiday-austria', 'Winter Holiday in Austria', 'tour', 'Austria', 'Europe', 'Vienna', 'Experience the magic of Austria this winter with our specially designed holiday package. From the snow-covered Alps to the charming streets of Vienna and Salzburg, Austria offers the perfect blend of natural beauty, culture and festive spirit. Enjoy skiing on world-famous slopes, wander through traditional Christmas markets, and admire breathtaking alpine scenery, warmed by authentic Austrian cuisine and cosy mountain lodges.', 5, 6, '', 4999, 'AED', 4, 5, 0, 1, 23, '', '[]', '["Winter","Ski","Europe"]', '[]', '["Skiing the Austrian Alps","Vienna & Salzburg","Traditional Christmas markets","Cosy mountain lodges"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('uzbekistan-tashkent-tour', 'Uzbekistan, Tashkent Tour', 'tour', 'Uzbekistan', 'Central Asia', 'Tashkent', 'Discover the timeless beauty of Uzbekistan with our specially designed tour package through the heart of Central Asia''s rich history and culture. Explore the majestic cities of Samarkand, Bukhara and Khiva, where ancient Silk Road routes once thrived, and marvel at stunning Islamic architecture, vibrant bazaars and centuries-old monuments — from turquoise-domed madrasahs and grand mosques to bustling markets filled with local crafts and spices.', 3, 4, '', 2650, 'AED', 4, 5, 0, 1, 24, '', '[]', '["Culture","History","Silk Road"]', '[]', '["Samarkand","Bukhara","Khiva","Silk Road bazaars"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('kyrgyzstan-bishkek-tour', 'Kyrgyzstan, Bishkek', 'tour', 'Kyrgyzstan', 'Central Asia', 'Bishkek', 'Experience the charm of Bishkek, Kyrgyzstan, with our exclusive tour package that blends natural beauty, cultural heritage and modern city life. Nestled at the foot of the majestic Tien Shan mountains, Bishkek welcomes you with wide boulevards, green parks and vibrant bazaars. Explore Ala-Too Square, the National Museum and Osh Bazaar for a taste of local life, or take a short escape to breathtaking landscapes like Ala Archa National Park.', 3, 4, '', 2499, 'AED', 4, 5, 0, 1, 25, '', '[]', '["Nature","Culture","Adventure"]', '[]', '["Ala-Too Square","The National Museum","Osh Bazaar","Ala Archa National Park"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('summer-holidays-umrah', 'Summer Holidays Umrah Package', 'umrah', 'Saudi Arabia', 'Middle East', 'Makkah & Madinah', 'Answer the call of your heart this Ramadan 🤍 Perform Umrah in the most blessed days with comfort, care and complete arrangements.', 6, 7, '', 3999, 'AED', 4, 5, 0, 1, 26, '', '[]', '["Spiritual","Umrah"]', '[]', '[]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('umrah-package', 'Umrah Package — 8 Days / 7 Nights', 'umrah', 'Saudi Arabia', 'Middle East', 'Makkah & Madinah', 'Fulfil your spiritual duty with our Umrah package, designed to provide comfort, ease and peace of mind throughout your sacred journey. From seamless visa processing and comfortable accommodation near the holy mosques to guided assistance at every step, we ensure your pilgrimage remains focused on worship and devotion.', 7, 8, 'Quad sharing', 4999, 'AED', 4, 5, 0, 1, 27, 'https://images.unsplash.com/photo-1591604129939-f1efa4d9f7fa?auto=format&fit=crop&w=1200&q=80', '["https://images.unsplash.com/photo-1591604129939-f1efa4d9f7fa?auto=format&fit=crop&w=1200&q=80"]', '["Spiritual","Umrah"]', '["Umrah visa","4★ hotels near the Haram","Ziyarat tours","Inter-city transfers"]', '["Hotels steps from the Haram","Guided Ziyarat in both cities","Group & family options","Complete visa handling"]', '[{"day":1,"title":"Arrival in Madinah","detail":"Transfer to your hotel near Masjid an-Nabawi."},{"day":2,"title":"Madinah Ziyarat","detail":"Guided visits to the holy sites of Madinah."},{"day":3,"title":"Travel to Makkah","detail":"Comfortable transfer and performing of Umrah."},{"day":4,"title":"Worship & Reflection","detail":"Days of worship at Masjid al-Haram at your own pace."},{"day":8,"title":"Departure","detail":"Final prayers and transfer to the airport."}]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('umrah-package-12-days', 'Umrah Package — 12 Days / 11 Nights', 'umrah', 'Saudi Arabia', 'Middle East', 'Makkah & Madinah', 'Embark on a blessed 12-day spiritual journey with our Umrah package, thoughtfully designed to give you ample time for worship, reflection and peace in the holy cities of Makkah and Madinah. Enjoy comfortable accommodation close to the Haram, seamless visa assistance and guided support throughout your stay. With extended days you have the opportunity to perform your rituals with ease, visit sacred sites, and experience the true serenity of this once-in-a-lifetime pilgrimage.', 11, 12, '', 6499, 'AED', 4, 5, 0, 1, 28, '', '[]', '["Spiritual","Umrah"]', '["Umrah visa","Hotels near the Haram","Ziyarat tours","Inter-city transfers"]', '["Extended time for worship","Hotels close to the Haram","Guided support throughout","Complete visa handling"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO `Destination` (`name`, `blurb`, `image`, `priceFrom`, `packageSlug`, `published`, `order`, `createdAt`, `updatedAt`) VALUES
