INSERT INTO `Visa` (`country`, `flag`, `type`, `processing`, `note`, `price`, `about`, `documentsRequired`, `documentsProvided`, `published`, `order`, `createdAt`, `updatedAt`) VALUES
  ('United States', '🇺🇸', 'B1/B2 Tourist & Business', '3–6 weeks', 'Early appointment support & DS-160 prep', 'AED 1,500', 'Get your journey started hassle-free with our USA Visit Visa assistance and early appointment support. Whether you''re travelling for tourism, family visits or business, our experienced team guides you through the entire process — filling out your DS-160, organising documents and preparing you for the interview. We also help secure early appointment slots, saving you time and avoiding long delays. Reduce errors, speed up the process and boost your chances of approval while you focus on planning your American adventure.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)","Invitation Letter from Inviting Company (business visa)","Trade Licence Copy (if owner/partner is travelling)"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Itinerary","Interview Preparation","24/7 Support"]', 1, 0, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('United Kingdom', '🇬🇧', 'Standard Visitor', '3–4 weeks', 'Document checklist & interview prep', 'AED 2,000', 'We''re here to make your journey smooth and hassle-free with our UK Visit Visa assistance. Whether you''re visiting for tourism, to meet family and friends, or to explore business opportunities, our expert team guides you through every step of the process — from filling out the application form accurately to organising your documents and preparing you for the visa interview. Save time, avoid mistakes and increase your chances of approval while you focus on planning your trip to the UK.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)","6 Months Bank Statement","Company NOC Letter","Salary Certificate","Previous Travel History (optional)","Trade Licence Copy (if owner/partner is travelling)"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Itinerary","Travel Insurance","24/7 Support"]', 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Schengen', '🇪🇺', 'Short-stay (Type C)', '2–3 weeks', 'Covers 27 European countries', 'AED 1,000', 'Dreaming of exploring Europe? Our Schengen Visit Visa assistance makes the process simple, quick and stress-free. Whether you want to experience the romance of Paris, the history of Rome or the beauty of Switzerland, our expert team guides you through the entire visa process — filling out your application forms, preparing the required documents, booking appointments and offering guidance to boost your chances of approval. One visa, twenty-seven Schengen countries. Let us handle the paperwork so you can focus on your European adventure.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)","6 Months Bank Statement","Company NOC Letter","Previous Travel History (optional)","Trade Licence Copy (if owner/partner is travelling)"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Itinerary","Biometric Appointment","Travel Insurance","24/7 Support"]', 1, 2, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Canada', '🇨🇦', 'Visitor Visa (TRV)', '4–8 weeks', 'Biometrics appointment included', 'AED 1,500', 'Planning to visit Canada? Our Canada Visit Visa assistance makes the process simple, accurate and stress-free. Whether you''re travelling for tourism, meeting family and friends, or exploring business opportunities, our expert team guides you through every step — filling out the application forms correctly, organising the required documents, booking appointments and providing personalised guidance to increase your chances of approval. Avoid delays and mistakes while you prepare to experience the beauty and charm of Canada.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)","6 Months Bank Statement","Company NOC Letter","Previous Travel History (optional)","Invitation Letter from Inviting Company (business visa)","Trade Licence Copy (if owner/partner is travelling)"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Itinerary","Biometric Appointment","24/7 Support"]', 1, 3, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Australia', '🇦🇺', 'Visitor (Subclass 600)', '2–4 weeks', 'Online lodgement handled for you', 'AED 1,500', 'Our Australia Visit Visa assistance makes the process simple, smooth and stress-free. Whether you''re visiting for tourism, family or business, our expert team guides you step by step — filling out your application accurately, preparing the required documents and ensuring everything is submitted correctly. Avoid costly mistakes, save time and increase your chances of approval while you get ready to experience the beauty of Australia, from the Sydney Opera House and the Great Barrier Reef to breathtaking beaches and unique wildlife.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)","3–6 Months Bank Statement","Company NOC Letter","Salary Certificate","Previous Travel History (optional)","Invitation Letter from Inviting Company (business visa)","Trade Licence Copy (if owner/partner is travelling)"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Itinerary","Biometric Appointment","24/7 Support"]', 1, 4, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('New Zealand', '🇳🇿', 'Visitor Visa', '3–5 weeks', 'End-to-end application support', 'AED 2,000', 'Our New Zealand Visit Visa assistance makes your journey easy, smooth and stress-free. Whether you''re travelling for tourism, family visits or business, our expert team assists with every step — filling out the visa application, organising the required documents and guiding you through the entire process. Avoid delays, reduce errors and improve your chances of approval while you prepare to experience New Zealand''s stunning landscapes, vibrant culture and warm Kiwi hospitality.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)","3–6 Months Bank Statement","Company NOC Letter","Salary Certificate","Previous Travel History (optional)","Invitation Letter from Inviting Company (business visa)","Trade Licence Copy (if owner/partner is travelling)"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Itinerary","Travel Insurance (if needed)","24/7 Support"]', 1, 5, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Türkiye', '🇹🇷', 'Visit Visa', '2–3 weeks', 'Appointment booking & full document prep', 'AED 1,499', 'Discover the charm of Türkiye — where East meets West. Apply for your Türkiye Visit Visa from Dubai effortlessly with our professional visa assistance. Whether you''re planning to stroll through the historic streets of Istanbul, relax in Cappadocia''s hot air balloons, or unwind on Antalya''s beaches, we make your visa process fast, simple and stress-free. Our experienced team takes care of everything — from filling out your application form and arranging documents to booking appointments and ensuring smooth submission.', '["Original Passport (valid 6+ months)","Valid UAE Residence Visa (6+ months validity)","Recent Passport-size Photo (white background)","Company NOC Letter or Trade Licence (if self-employed)","3 Months Bank Statement"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Itinerary","Embassy Fee","24/7 Support"]', 1, 6, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('China', '🇨🇳', 'Visit Visa', '2–3 weeks', 'Transparent fees — no hidden charges', 'AED 999', 'Planning to explore the wonders of China? Apply for your China Visit Visa from Dubai with our expert assistance. Whether you''re visiting family and friends or exploring landmarks like the Great Wall, the Forbidden City or Shanghai''s skyline, we make your visa process smooth and stress-free. Our team guides you through every step — from document preparation to form filling, appointment booking and submission.', '["Original Passport (valid 6+ months)","Passport-size Photo (white background)","Company NOC Letter or Trade Licence (if self-employed)","3 Months Bank Statement","Invitation Letter (if applicable)"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Itinerary","Embassy Fee","Transparent Fees — No Hidden Charges","24/7 Support"]', 1, 7, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Senegal', '🇸🇳', 'Visit Visa', '2–3 weeks', 'Tourism, family visits & business', 'AED 1,000', 'Our Senegal Visit Visa assistance makes the process simple, accurate and stress-free. Whether you''re travelling for tourism, family visits or business, our expert team guides you through every step — filling out your application properly, preparing the required documents and ensuring a smooth submission. Save time, avoid errors and improve your chances of approval while you get ready to explore Senegal''s vibrant markets, historic landmarks, golden beaches and warm West African hospitality.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Itinerary","Embassy Fee","24/7 Support"]', 1, 8, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Venezuela', '🇻🇪', 'Visit Visa', '3–4 weeks', 'Full document handling end-to-end', 'AED 2,000', 'Our Venezuela Visit Visa assistance is designed to make your visa process easy, quick and stress-free. Whether you''re travelling for tourism, family visits or business, our expert team helps you accurately complete your application, prepare and organise the required documents, and guides you through each step of submission — so you can get ready to explore Venezuela''s breathtaking Angel Falls, stunning beaches, lively culture and warm hospitality with peace of mind.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)","Company NOC Letter","3 Months Bank Statement"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Itinerary","Embassy Fee","24/7 Support"]', 1, 9, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Russia', '🇷🇺', 'Visit Visa', '2–3 weeks', 'Timely submission, fewer delays', 'AED 2,000', 'Our Russia Visit Visa assistance keeps the process smooth, accurate and stress-free. Whether you''re travelling for tourism, family visits or business, our expert team guides you through every step — completing your application correctly, organising the required documents and ensuring timely submission. Reduce errors, avoid delays and improve your chances of approval while you prepare to experience Russia''s iconic landmarks, from Red Square and the Kremlin to breathtaking palaces and cathedrals.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Itinerary","Embassy Fee","24/7 Support"]', 1, 10, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Philippines', '🇵🇭', 'Visit Visa', '2–3 weeks', 'Simple, fast & fully assisted', 'AED 1,099', 'Our Philippines Visit Visa assistance makes your visa process simple, fast and stress-free. Whether you''re travelling for tourism, family visits or business, our expert team assists with every step — accurately filling out your application, preparing the required documents and ensuring smooth submission. Avoid mistakes, save time and increase your chances of approval while you get ready to enjoy the Philippines'' pristine beaches, vibrant cities, rich culture and warm hospitality.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Itinerary","Embassy Fee","24/7 Support"]', 1, 11, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Malaysia', '🇲🇾', 'Visit Visa', '1–2 weeks', 'Quick turnaround, minimal paperwork', 'AED 999', 'Our Malaysia Visit Visa assistance ensures your visa process is smooth, quick and stress-free. Whether you''re travelling for tourism, family visits or business, our expert team guides you step by step — filling out your application accurately, preparing the required documents and submitting everything correctly. Avoid delays, reduce errors and improve your chances of approval while you prepare to experience Malaysia''s stunning skyscrapers, tropical islands, diverse culture and world-famous hospitality.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Itinerary","Embassy Fee","24/7 Support"]', 1, 12, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Tajikistan', '🇹🇯', 'Visit Visa', '2–3 weeks', 'Documents organised & submitted for you', 'AED 1,200', 'Our Tajikistan Visit Visa assistance makes the process simple and stress-free. Whether you''re travelling for tourism, family visits or business, our expert team guides you through each step — accurately filling out your application, preparing and organising the required documents and ensuring a smooth submission. Avoid errors, save time and increase your chances of approval while you get ready to explore Tajikistan''s breathtaking mountains, rich culture and warm hospitality.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Itinerary","Embassy Fee","24/7 Support"]', 1, 13, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Indonesia', '🇮🇩', 'Visit Visa', '1–2 weeks', 'Tourism, family & business travel', 'AED 1,200', 'Our Indonesia Visit Visa assistance makes the process easy, fast and stress-free. Whether you''re visiting for tourism, family or business, our expert team guides you through every step — accurately filling out your application, preparing the required documents and ensuring smooth submission. Avoid delays, minimise errors and improve your chances of approval while you prepare to explore Indonesia''s stunning beaches, lush jungles, vibrant culture and world-famous destinations like Bali and Jakarta.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Itinerary","Embassy Fee","24/7 Support"]', 1, 14, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Morocco', '🇲🇦', 'Visit Visa', '2–3 weeks', 'Documents organised & submitted for you', 'AED 1,000', 'Our Morocco Visit Visa assistance is designed to make the entire process smooth and stress-free. Whether you''re travelling for tourism, family visits or business, our expert team helps you fill out your application accurately, prepare and organise the required documents, and guides you through every step of submission. Avoid errors, save valuable time and increase your chances of approval while you get ready to experience Morocco''s vibrant souks, stunning deserts and breathtaking historic cities.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Itinerary","Embassy Fee","24/7 Support"]', 1, 15, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Thailand', '🇹🇭', 'Visit Visa', '1–2 weeks', 'Quick, smooth & hassle-free', 'AED 1,500', 'Our Thailand Visit Visa assistance makes the process quick, smooth and hassle-free. Whether you''re planning a holiday to enjoy Thailand''s golden beaches, vibrant nightlife and cultural temples, or visiting family and friends, our expert team guides you through every step. We assist with filling out your application forms, preparing the necessary documents and ensuring everything is submitted correctly to avoid delays. Save time, reduce errors and boost your chances of approval while you get ready to enjoy the Land of Smiles.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Itinerary","Embassy Fee","24/7 Support"]', 1, 16, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Japan', '🇯🇵', 'Visit Visa', '2–3 weeks', 'Full document prep & submission', 'AED 1,500', 'Our Japan Visit Visa assistance makes the process simple and stress-free. Whether you''re travelling for tourism, family visits or business, our expert team guides you through every step — filling out your visa application accurately, preparing and organising the required documents and ensuring a smooth submission. Avoid mistakes, save time and increase your chances of approval while you get ready to explore Japan''s unique blend of tradition and modernity, from ancient temples and cherry blossoms to futuristic cities and world-class cuisine.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)","3 Months Bank Statement (if available)"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Itinerary","Embassy Fee","24/7 Support"]', 1, 17, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO `Testimonial` (`name`, `trip`, `rating`, `quote`, `published`, `order`, `createdAt`, `updatedAt`) VALUES
  ('Ali R.', 'Escape to Armenia', 5, 'My Armenia trip was seamless. Hotels, transfers, and sightseeing were perfectly organised. Highly recommend RadiantWay Travel!', 1, 0, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Fatima S.', 'Discover Istanbul', 5, 'Booking the Turkey package was effortless. Everything from flights to hotel transfers was handled professionally. Istanbul sightseeing was amazing!', 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Omar K.', 'Russian Adventure', 5, 'The Russia package exceeded my expectations. Day trips around Moscow were well organised, and the hotel stay was very comfortable. Truly stress-free travel!', 1, 2, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Sara M.', 'Maldives Getaway', 5, 'An absolute dream. From the speedboat transfer to the overwater villa, every detail was taken care of. We just relaxed and enjoyed our honeymoon.', 1, 3, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Bilal A.', 'Umrah Journey', 5, 'A spiritually beautiful and perfectly organised Umrah. Hotels were minutes from the Haram and the team supported us every single step of the way.', 1, 4, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO `Faq` (`question`, `answer`, `published`, `order`, `createdAt`, `updatedAt`) VALUES
  ('Do you arrange the flights?', 'Yes, all our packages include return flights from major UAE airports, ensuring a seamless travel experience from start to finish.', 1, 0, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Are the hotels central/close to attractions?', 'Yes, we carefully select hotels that are centrally located and close to major attractions, offering both comfort and convenience.', 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Do you help with visa applications?', 'Yes — we handle 18 destinations, including the USA, UK, Schengen, Canada, Australia, New Zealand, Türkiye, China, Japan, Thailand, Malaysia, Indonesia, the Philippines, Russia, Morocco, Senegal, Venezuela and Tajikistan. Our team guides you through the entire process.', 1, 2, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Can I book for solo travellers or families?', 'Yes, our packages are flexible and can be tailored for solo travelers, families, or groups, ensuring everyone enjoys a smooth and memorable journey.', 1, 3, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Do you offer installment payment options?', 'Yes, we offer easy installment plans. You can secure your booking with a small deposit and pay the remaining amount through flexible installments before departure.', 1, 4, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO `Service` (`icon`, `title`, `description`, `group`, `published`, `order`, `createdAt`, `updatedAt`) VALUES
  ('Map', 'Tour Packages', 'Curated multi-day itineraries with hotels, sightseeing and transfers bundled into one easy price.', 'service', 1, 0, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('StampIcon', 'Visa Assistance', 'End-to-end visa support for 18 destinations — from the USA, UK and Schengen to Japan, Thailand, Türkiye and beyond.', 'service', 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Plane', 'Flight Bookings', 'Competitive fares on every major airline, included and optimised within your package.', 'service', 1, 2, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('BedDouble', 'Hotel Arrangements', 'Hand-picked 3★ to 5★ stays, from cosy city hotels to beachfront resorts.', 'service', 1, 3, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('CarFront', 'Airport Transfers', 'Private, comfortable pick-ups and drop-offs so your journey is seamless from door to door.', 'service', 1, 4, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Camera', 'Sightseeing & Tours', 'Guided experiences and day trips that put the very best of every destination on your itinerary.', 'service', 1, 5, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('CreditCard', 'Installment Plans', 'Travel now, pay comfortably later with flexible, interest-friendly payment options.', 'service', 1, 6, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Ferris', 'Dubai Activities', 'Desert safaris, Burj Khalifa, dhow cruises and the full spectrum of Dubai experiences.', 'service', 1, 7, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('MoonStar', 'Umrah Packages', 'Spiritually enriching, professionally organised Umrah journeys with complete peace of mind.', 'service', 1, 8, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Globe', 'UAE-based, global reach', 'Headquartered in the UAE, we proudly serve travelers from around the world with trusted expertise.', 'why', 1, 9, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Map', 'Tailored packages', 'We craft personalized travel packages designed to suit your preferences, budget, and schedule.', 'why', 1, 10, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Wallet', 'Affordable quad-sharing', 'Save more by choosing our cost-effective quad-sharing accommodation options on group tours.', 'why', 1, 11, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Clock', '24/7 visa support & assistance', 'Get round-the-clock visa guidance and travel support for top destinations like the USA, UK, and Schengen countries.', 'why', 1, 12, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO `Setting` (`key`, `value`, `updatedAt`) VALUES
  ('company', '{"name":"RadiantWay Travel","shortName":"RadiantWay","tagline":"Effortless Journeys. Lasting Memories.","intro":"UAE-based travel experts with global reach. We craft tailored tour packages, handle your visas, and take care of every detail — so all you have to do is travel.","phone":"+971 54 786 1293","phoneHref":"tel:+971547861293","holidaysPhone":"+971 54 786 1293","visaPhone":"+971 54 786 1293","whatsapp":"https://wa.me/971547861293","email":"info@radiantwaytravel.com","emailHref":"mailto:info@radiantwaytravel.com","address":"Office No: 17, 28th Floor, Aspin Commercial Tower, Sheikh Zayed Road, Dubai, UAE","hours":"Open 24/7 — we never stop for our travellers","reviewUrl":"https://share.google/6Yg4AJOHDoq0k574Q","socials":[{"name":"Instagram","href":"https://www.instagram.com/radiantwaytravel?igsh=MW90NXQyaGl0bWZwdg==","icon":"Instagram"},{"name":"Facebook","href":"https://www.facebook.com/share/19qorzUXsM/","icon":"Facebook"},{"name":"WhatsApp","href":"https://wa.me/971547861293","icon":"MessageCircle"}],"rating":4.7,"reviewCount":39,"stats":[{"value":8,"suffix":"+","label":"Years of expertise"},{"value":50,"suffix":"k+","label":"Happy travellers"},{"value":40,"suffix":"+","label":"Destinations worldwide"},{"value":4.7,"suffix":"★","label":"Rated by 39+ reviews","decimals":1}]}', CURRENT_TIMESTAMP(3));
